// ─── HOOK ────────────────────────────────────────────────────────────────────

export function useCompareArticleSettings() {
  const { data: settingsArray, isLoading } = trpc.settings.getAll.useQuery({});

  // Build a lookup map from the settings array
  const settingsMap = useMemo(() => {
    const map: Record<string, string> = {};
    if (settingsArray) {
      settingsArray.forEach((s: { key: string; value: string }) => {
        if (s.key.startsWith('compare_')) {
          map[s.key] = s.value;
        }
      });
    }
    return map;
  }, [settingsArray]);

  // Helper: get a setting value or fall back to default
  const get = (key: string, fallback: string): string => {
    const val = settingsMap[key];
    return (val && val.trim() !== '') ? val : fallback;
  };

  // Helper: try to parse JSON setting, fall back to default
  const getJSON = <T,>(key: string, fallback: T): T => {
    const val = settingsMap[key];
    if (val && val.trim() !== '') {
      try {
        return JSON.parse(val) as T;
      } catch {
        return fallback;
      }
    }
    return fallback;
  };

  // Build the resolved content
  const author = useMemo(() => ({
    name: get('compare_author_name', DEFAULT_AUTHOR.name),
    credential: get('compare_author_credential', DEFAULT_AUTHOR.credential),
    avatar: get('compare_author_avatar', DEFAULT_AUTHOR.avatar),
    bio: get('compare_author_bio', DEFAULT_AUTHOR.bio),
    shortBio: get('compare_author_short_bio', DEFAULT_AUTHOR.shortBio),
  }), [settingsMap]);

  const article = useMemo(() => ({
    title: get('compare_title', DEFAULT_ARTICLE.title),
    heroImage: get('compare_hero_image', DEFAULT_ARTICLE.heroImage),
    heroCaption: get('compare_hero_caption', DEFAULT_ARTICLE.heroCaption),
  }), [settingsMap]);

  const intro = useMemo(() => ({
    p1: get('compare_intro_p1', DEFAULT_INTRO.p1),
    p2: get('compare_intro_p2', DEFAULT_INTRO.p2),
    p3: get('compare_intro_p3', DEFAULT_INTRO.p3),
  }), [settingsMap]);

  const groundRules = useMemo(() => [
    {
      title: get('compare_rule_1_title', DEFAULT_GROUND_RULES[0].title),
      desc: get('compare_rule_1_desc', DEFAULT_GROUND_RULES[0].desc),
    },
    {
      title: get('compare_rule_2_title', DEFAULT_GROUND_RULES[1].title),
      desc: get('compare_rule_2_desc', DEFAULT_GROUND_RULES[1].desc),
    },
    {
      title: get('compare_rule_3_title', DEFAULT_GROUND_RULES[2].title),
      desc: get('compare_rule_3_desc', DEFAULT_GROUND_RULES[2].desc),
    },
  ], [settingsMap]);

  const testingSteps = useMemo(() => [
    get('compare_test_step_1', DEFAULT_TESTING_STEPS[0]),
    get('compare_test_step_2', DEFAULT_TESTING_STEPS[1]),
    get('compare_test_step_3', DEFAULT_TESTING_STEPS[2]),
    get('compare_test_step_4', DEFAULT_TESTING_STEPS[3]),
    get('compare_test_step_5', DEFAULT_TESTING_STEPS[4]),
    get('compare_test_step_6', DEFAULT_TESTING_STEPS[5]),
  ], [settingsMap]);

  const nonNegotiables = useMemo(() => [
    get('compare_nonneg_1', DEFAULT_NON_NEGOTIABLES[0]),
    get('compare_nonneg_2', DEFAULT_NON_NEGOTIABLES[1]),
    get('compare_nonneg_3', DEFAULT_NON_NEGOTIABLES[2]),
    get('compare_nonneg_4', DEFAULT_NON_NEGOTIABLES[3]),
    get('compare_nonneg_5', DEFAULT_NON_NEGOTIABLES[4]),
    get('compare_nonneg_6', DEFAULT_NON_NEGOTIABLES[5]),
  ], [settingsMap]);

  const verdict = useMemo(() => ({
    p1: get('compare_verdict_p1', DEFAULT_VERDICT.p1),
    p2: get('compare_verdict_p2', DEFAULT_VERDICT.p2),
    p3: get('compare_verdict_p3', DEFAULT_VERDICT.p3),
    p4: get('compare_verdict_p4', DEFAULT_VERDICT.p4),
    closing: get('compare_verdict_closing', DEFAULT_VERDICT.closing),
  }), [settingsMap]);

  return {
    isLoading,
    author,
    article,
    intro,
    groundRules,
    testingSteps,
    nonNegotiables,
    verdict,
    getJSON,
    // Export defaults for reference
    defaults: {
      author: DEFAULT_AUTHOR,
      article: DEFAULT_ARTICLE,
      intro: DEFAULT_INTRO,
      groundRules: DEFAULT_GROUND_RULES,
      testingSteps: DEFAULT_TESTING_STEPS,
      nonNegotiables: DEFAULT_NON_NEGOTIABLES,
      verdict: DEFAULT_VERDICT,
    },
  };
}

export default useCompareArticleSettings;
