// ─── HELPER COMPONENTS ───────────────────────────────────────────────────────

function StarRating({ rating, max = 10 }: { rating: number; max?: number }) {
  const stars = Math.round((rating / max) * 5 * 2) / 2; // half-star precision out of 5
  return (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((i) => (
        <Star
          key={i}
          className={`w-4 h-4 ${
            i <= Math.floor(stars)
              ? "fill-[#f5c542] text-[#f5c542]"
              : i - 0.5 <= stars
              ? "fill-[#f5c542]/50 text-[#f5c542]"
              : "fill-gray-200 text-gray-200"
          }`}
        />
      ))}
    </div>
  );
}

function RatingBadge({ rating, isBest }: { rating: number; isBest?: boolean }) {
  const bgColor = rating >= 9 ? "bg-[#22c55e]" : rating >= 8 ? "bg-[#84cc16]" : rating >= 7 ? "bg-[#eab308]" : "bg-[#f97316]";
  return (
    <div className={`${bgColor} text-white rounded-lg px-3 py-1.5 text-center min-w-[60px]`}>
      <div className="text-lg font-bold leading-tight">{rating}</div>
      {isBest && <div className="text-[9px] font-semibold uppercase tracking-wide opacity-90">Best</div>}
    </div>
  );
}

